_SECTION_BEGIN("SMA Crossover Optimization");

// Optimize the fast SMA period
FastPeriod = Optimize("Fast SMA", 20, 20, 200, 1);
SlowPeriod = Optimize("Slow SMA", 130, 100, 200, 5);
ExitPeriod = Optimize("Exit SMA", 30, 20, 200, 5);


// Fixed moving averages
FastSMA = MA(Close, FastPeriod);
SlowSMA = MA(Close, SlowPeriod);
ExitSMA = MA(Close, ExitPeriod);

// Buy when fast SMA crosses above SMA 200
Buy = Cross(FastSMA, SlowSMA);

// Sell when closing price falls below SMA 100
