_SECTION_BEGIN("HA Strict Portfolio RS ATR");

// =============================================
// 1. CONFIGURABLE SETTINGS
// =============================================

ConfirmBars = Optimize("HA Confirm Bars", 2, 1, 4, 1);
RSPeriod    = Optimize("Ranking Lookback", 63, 20, 120, 10);

MaxPositions = Param("Maximum Open Positions", 20, 1, 100, 1);
ATRPeriod    = Param("ATR Period", 14, 5, 50, 1);
ATRMultiple  = Param("ATR Trail Multiple", 3, 1, 6, 0.5);

// Activate profit protection after a sharp rise
VerticalRise = Param("Vertical Rise %", 15, 5, 50, 1);
RiseBars     = Param("Rise Lookback Bars", 5, 2, 20, 1);

SetChartOptions(0, chartShowDates | chartShowArrows);

SetOption("InitialEquity", 100000);
SetOption("MaxOpenPositions", MaxPositions);
SetOption("AllowPositionShrinking", True);

// Equal percentage of equity per position
SetPositionSize(100 / MaxPositions, spsPercentOfEquity);

// Next-bar execution at actual market prices
SetTradeDelays(1, 1, 1, 1);
BuyPrice = Open;
SellPrice = Open;

// =============================================
// 2. HEIKIN-ASHI CANDLES
// =============================================

HaClose = (O + H + L + C) / 4;

HaOpen = Null;
HaOpen[0] = (O[0] + C[0]) / 2;

for (i = 1; i < BarCount; i++)
{
    HaOpen[i] = (HaOpen[i-1] + HaClose[i-1]) / 2;
}

HaHigh = Max(H, Max(HaOpen, HaClose));
HaLow  = Min(L, Min(HaOpen, HaClose));

Bullish = HaClose > HaOpen;
Bearish = HaClose < HaOpen;

// =============================================
// 3. 200 SMA TREND FILTER
// =============================================

SMA200 = MA(C, 200);

TrendOK = C > SMA200;
Rising200 = SMA200 > Ref(SMA200, -20);

// =============================================
// 4. STRICT BUY / SELL CONDITIONS
// =============================================

BullCount = Sum(Bullish, ConfirmBars);

HAConfirmedBuy =
    BullCount == ConfirmBars AND
    Ref(Bullish, -ConfirmBars) == 0;

RSIValue = RSI(14);
MomentumOK = RSIValue > 55;

BuySetup =
    HAConfirmedBuy ;
//AND
   // TrendOK AND
   // Rising200 AND
    //MomentumOK;

BearCount = Sum(Bearish, ConfirmBars);

HAConfirmedSell =
    BearCount == ConfirmBars;

TrendExit = Cross(SMA200, C);

SellSetup = HAConfirmedSell;
//TrendExit OR HAConfirmedSell;

// =============================================
// 5. RANK STOCKS AGAINST OTHER STOCKS
// =============================================

// Rank by the stock's own percentage return.
// The portfolio backtester compares PositionScore
// among stocks generating BUY signals.

RankingScore = ROC(C, RSPeriod);

// Only buy stocks with positive lookback return
BuySetup = BuySetup AND RankingScore > 0;

Buy = BuySetup;
Sell = SellSetup;

Buy = ExRem(Buy, Sell);
Sell = ExRem(Sell, Buy);

Short = 0;
Cover = 0;

PositionScore = RankingScore;

// =============================================
// 6. ATR PROFIT PROTECTION
// =============================================

// A sharp rise activates the protective ATR trail.
// VerticalRise is the percentage gain over RiseBars.

RisePct = 100 * (C / Ref(C, -RiseBars) - 1);

ATRValue = ATR(ATRPeriod);

// ApplyStop provides a portfolio-level trailing stop.
// Its distance is ATR-based and may protect profits
// during strong price advances and subsequent reversals.

ApplyStop(
    stopTypeTrailing,
    stopModePoint,
    ATRMultiple * ATRValue,
    True,
    True
);

// =============================================
// 7. CHART PLOTTING
// =============================================

CandleColor =
    IIf(HaClose >= HaOpen, colorGreen, colorRed);

PlotOHLC(
    HaOpen,
    HaHigh,
    HaLow,
    HaClose,
    "Heikin-Ashi",
    CandleColor,
    styleCandle
);

Plot(SMA200, "SMA 200", colorBlue, styleLine);

PlotShapes(
    IIf(Buy, shapeUpArrow, shapeNone),
    colorBrightGreen, 0, HaLow, -20
);

PlotShapes(
    IIf(Sell, shapeDownArrow, shapeNone),
    colorRed, 0, HaHigh, -20
);

// =============================================
// 8. EXPLORATION
// =============================================

Filter = Buy OR Sell;

AddColumn(C, "Close", 1.2);
AddColumn(SMA200, "SMA 200", 1.2);
AddColumn(RankingScore, "Stock Return %", 1.2);
AddColumn(RSIValue, "RSI", 1.2);
AddColumn(RisePct, "Recent Rise %", 1.2);
AddColumn(ATRValue, "ATR", 1.2);

AddColumn(
    IIf(Buy, 1, -1),
    "Signal: 1 Buy / -1 Sell",
    1.0
);

