_SECTION_BEGIN("Nifty500 Momentum 50 - Index Style");

// =============================================
// SETTINGS
// =============================================

ReviewMonth1 = 6;   // June
ReviewMonth2 = 12;  // December

SetOption("InitialEquity", 100000);
SetOption("MaxOpenPositions", 50);
SetOption("AllowPositionShrinking", True);
SetTradeDelays(1, 1, 1, 1);

SetPositionSize(2, spsPercentOfEquity);

// =============================================
// MOMENTUM INPUTS
// =============================================

Return6  = C / Ref(C, -126) - 1;
Return12 = C / Ref(C, -252) - 1;

DailyLogReturn = Log(C / Ref(C, -1));
AnnualVol = StDev(DailyLogReturn, 252) * sqrt(252);
SafeVol = Max(AnnualVol, 0.0001);

MR6  = Return6 / SafeVol;
MR12 = Return12 / SafeVol;

// =============================================
// CROSS-SECTIONAL RANKING PROXY
// =============================================

// AmiBroker's portfolio engine ranks Buy candidates
// by PositionScore across the analysis universe.
//
// This proxy uses the average of the two momentum
// ratios. It is NOT the official cross-sectional
// Z-score calculation.

ScoreProxy = (MR6 + MR12) / 2;

PositionScore = ScoreProxy;

// =============================================
// SEMIANNUAL REVIEW DATES
// =============================================

// Last trading session of June and December.
// Detect month change on the daily chart.

MonthEnd = Month() != Ref(Month(), 1);

ReviewDay =
    MonthEnd AND
    (Ref(Month(), 1) == ReviewMonth1 OR
     Ref(Month(), 1) == ReviewMonth2);

// =============================================
// PORTFOLIO SIGNALS
// =============================================

// All eligible symbols become candidates on review.
// The backtester selects highest PositionScore first.
// MaxOpenPositions limits holdings to 50.

HistoryOK = BarIndex() >= 252;

Buy = ReviewDay AND HistoryOK AND ScoreProxy > 0;

// Exit and refresh the portfolio on review dates.
// This simple version does not retain the official
// constituent buffer or rank-based holdover rules.

Sell = ReviewDay;

// =============================================
// EXPLORATION OUTPUT
// =============================================

Filter = Status("lastbarinrange");

AddColumn(C, "Close", 1.2);
AddColumn(Return6 * 100, "6M Return %", 1.2);
AddColumn(Return12 * 100, "12M Return %", 1.2);
AddColumn(AnnualVol * 100, "Annual Volatility %", 1.2);
AddColumn(ScoreProxy, "Momentum Proxy", 1.4);

_SECTION_END();","description":"","kind":"exploration","weight":null,"created":1792514240407,"updated":1792516621293},{"id":"u:mvjxnhdy0","name":"Qullamaggie Breakout","code":"//==============================================================================
// QULLAMAGGIE-STYLE BREAKOUT SETUP  (Daily chart)  -  AmiBroker AFL
//
// Source rules: "My 3 timeless setups" (qullamaggie.com), Breakouts section
//
//  1. LEADERS   : stocks in the top 1-2% by 1-month / 3-month / 6-month gain
//  2. BIG MOVE  : 30-100%+ advance sometime in the past 1-3 months
//  3. CONSOLIDATION (2 weeks - 2 months): orderly pullback, HIGHER LOWS,
//                 TIGHTENING range, price "surfs" the rising 10 & 20-day MA
//  4. ENTRY     : range expansion out of the consolidation (opening-range high
//                 on intraday charts; on daily bars = break of the recent high)
//  5. STOP      : low of the entry day, never wider than the stock's ADR
//  6. EXIT      : sell 1/3 - 1/2 after 3-5 days, move stop to break-even,
//                 trail the rest with the 10-day (beginner) or 20-day MA and
//                 sell on the first CLOSE below it
//  7. RISK      : ~0.25-1% of equity per trade, position <= 30% of equity
//
// HOW TO USE
//  - Chart  : drag onto a chart (yellow dot = watchlist candidate, green arrow
//             = breakout bar, orange line = tomorrow's trigger price).
//  - Explore: Analysis > Explore. Shows both "WATCH" (setup ready, waiting for
//             trigger) and "BREAKOUT" (triggered today). Run after the close.
//  - Scan   : Analysis > Scan gives Buy signals on breakout bars.
//  - Backtest: Analysis > Backtest (Portfolio). Same-bar entries, so trade
//             delays are set to 0 inside the code.
//
// NOTES
//  - Only EOD data is used. The article enters on intraday opening-range highs;
//    here the entry is modelled as max(Open, trigger) on the breakout bar.
//  - All numeric defaults are starting points, not values from the article
//    (the article gives ranges). Tune them to your market.
//  - Traded value is in your own currency (default 1 crore if you trade NSE).
//  - Partial profit is a scale-out signal (Buy = sigScaleOut) sized with
//    SetPositionSize(..., spsPercentOfPosition). Check it on a few trades, and
//    check the rank direction (rank 1 = strongest), before trusting backtests.
//==============================================================================

_SECTION_BEGIN("QM Breakout - Universe");
MinPrice     = Param("Min price", 20, 0, 100000, 1);
MinTradedVal = Param("Min avg traded value (50d, close*vol)", 10000000, 0, 1e12, 1000000);
MinADR       = Param("Min ADR % (20d)", 4, 0, 30, 0.5);
_SECTION_END();

_SECTION_BEGIN("QM Breakout - Leaders");
UseRank  = ParamToggle("Rank vs watchlist (Explore/Scan/Backtest only)", "Off|On", 0);
WLNo     = Param("Watchlist no. used for ranking", 0, 0, 255, 1);
TopPct   = Param("Top % of universe (rank mode)", 2, 0.5, 25, 0.5);
Roc1Min  = Param("Fallback: 1-month gain % min", 25, 0, 500, 5);
Roc3Min  = Param("Fallback: 3-month gain % min", 50, 0, 1000, 5);
Roc6Min  = Param("Fallback: 6-month gain % min", 80, 0, 2000, 5);
_SECTION_END();

_SECTION_BEGIN("QM Breakout - Pattern");
SurgeLB    = Param("Big-move lookback (bars, ~3 months)", 63, 21, 126, 1);
SurgeMin   = Param("Big-move min % (low to high)", 30, 10, 300, 5);
ConsMin    = Param("Consolidation min bars (~2 weeks)", 10, 3, 60, 1);
ConsMax    = Param("Consolidation max bars (~2 months)", 40, 10, 120, 1);
MaxPB      = Param("Max pullback % from surge high", 30, 5, 60, 1);
ReqHL      = ParamToggle("Require higher lows", "No|Yes", 1);
TightRatio = Param("Tightening: recent range / prior range <", 1.0, 0.3, 1.5, 0.05);
SurfDays   = Param("Closes >= 20d MA in last 10 bars (min)", 8, 0, 10, 1);
PivotLen   = Param("Pivot (consolidation high) length, bars", 10, 3, 60, 1);
NearPct    = Param("Close within % of pivot", 4, 0.5, 15, 0.5);
_SECTION_END();

_SECTION_BEGIN("QM Breakout - Trigger / Exit / Risk");
RangeExp   = Param("Range expansion: day range >= x * ATR(14)", 1.0, 0.5, 3, 0.1);
VolMult    = Param("Volume >= x * 20d avg volume", 1.0, 0, 5, 0.1);
TrailLen   = Param("Trail MA length (10 = beginner, 20 = faster stocks)", 10, 5, 50, 1);
PartialOn  = ParamToggle("Take partial profit", "No|Yes", 1);
PartialDay = Param("Partial after N days (3-5)", 4, 1, 10, 1);
PartialPct = Param("Partial % of position (33-50)", 33, 10, 90, 1);
RiskPct    = Param("Risk per trade % of equity", 0.5, 0.1, 2, 0.05);
MaxPosPct  = Param("Max position % of equity", 30, 5, 100, 1);
MaxOpen    = Param("Max open positions", 10, 1, 50, 1);
_SECTION_END();

_SECTION_BEGIN("QM Breakout - Market filter");
IdxSym = ParamStr("Market index symbol (blank = off)", "");
_SECTION_END();

//------------------------------------------------------------------------------
// Optional market filter: index 10d MA > 20d MA and index close > 20d MA
// (a simple "bullish market" proxy; the article says breakouts work in bull
// markets and to trade less or not at all otherwise)
//------------------------------------------------------------------------------
MarketOK = 1;
if( IdxSym != "" )
{
    SetForeign( IdxSym );
    ixC  = C;
    ixM10 = MA( C, 10 );
    ixM20 = MA( C, 20 );
    RestorePriceArrays();
    MarketOK = ixM10 > ixM20 AND ixC > ixM20;
}

//------------------------------------------------------------------------------
// Basic stock arrays
//------------------------------------------------------------------------------
ADR     = 100 * ( MA( H / L, 20 ) - 1 );       // average daily range %
TrdVal  = MA( C * V, 50 );
MA10    = MA( C, 10 );
MA20    = MA( C, 20 );
MA50    = MA( C, 50 );
Roc1    = ROC( C, 21 );                         // ~1 month
Roc3    = ROC( C, 63 );                         // ~3 months
Roc6    = ROC( C, 126 );                        // ~6 months

Liquid  = C >= MinPrice AND TrdVal >= MinTradedVal AND ADR >= MinADR;

//------------------------------------------------------------------------------
// 1) LEADERS - top x% by 1M / 3M / 6M gain (any of the three timeframes)
//------------------------------------------------------------------------------
RankMode = UseRank AND Status( "action" ) != actionIndicator;
Rk1 = Rk3 = Rk6 = 999999;
Tot = 1;

if( RankMode )
{
    if( Status( "stocknum" ) == 0 )
    {
        List = CategoryGetSymbols( categoryWatchlist, WLNo );
        StaticVarSet( "qmTotal", StrCount( List, "," ) + 1 );

        for( k = 0; ( Sym = StrExtract( List, k ) ) != ""; k++ )
        {
            SetForeign( Sym );
            StaticVarSet( "qmr1" + Sym, ROC( C, 21 ) );
            StaticVarSet( "qmr3" + Sym, ROC( C, 63 ) );
            StaticVarSet( "qmr6" + Sym, ROC( C, 126 ) );
            RestorePriceArrays();
        }

        StaticVarGenerateRanks( "rank", "qmr1", 0, 1224 );
        StaticVarGenerateRanks( "rank", "qmr3", 0, 1224 );
        StaticVarGenerateRanks( "rank", "qmr6", 0, 1224 );
    }

    ThisSym = Name();
    Rk1 = Nz( StaticVarGet( "rankqmr1" + ThisSym ), 999999 );
    Rk3 = Nz( StaticVarGet( "rankqmr3" + ThisSym ), 999999 );
    Rk6 = Nz( StaticVarGet( "rankqmr6" + ThisSym ), 999999 );
    Tot = Max( StaticVarGet( "qmTotal" ), 1 );

    cut    = Tot * TopPct / 100;
    Leader = Rk1 <= cut OR Rk3 <= cut OR Rk6 <= cut;
}
else
{
    Leader = Roc1 >= Roc1Min OR Roc3 >= Roc3Min OR Roc6 >= Roc6Min;
}

//------------------------------------------------------------------------------
// 2) BIG MOVE in the past 1-3 months (low came BEFORE the high)
//------------------------------------------------------------------------------
SurgeHi = HHV( H, SurgeLB );
SurgeLo = LLV( L, SurgeLB );
Surge   = ( SurgeHi / SurgeLo - 1 ) * 100 >= SurgeMin
          AND LLVBars( L, SurgeLB ) > HHVBars( H, SurgeLB );

//------------------------------------------------------------------------------
// 3) CONSOLIDATION - 2 weeks to 2 months, orderly pullback, higher lows,
//    tightening range, price surfing the rising 10 & 20-day MA
//------------------------------------------------------------------------------
ConsBars = HHVBars( H, SurgeLB );               // bars since the surge high
ConsOK   = ConsBars >= ConsMin AND ConsBars <= ConsMax;

Pullback = ( SurgeHi - LLV( L, ConsMin ) ) / SurgeHi * 100 <= MaxPB;

Low5     = LLV( L, 5 );
HigherLo = Low5 > Ref( Low5, -5 );

Rng5     = MA( ( H - L ) / C, 5 );
RngPrev  = Ref( MA( ( H - L ) / C, 10 ), -5 );
Tight    = Rng5 < RngPrev * TightRatio;

Surf     = C > MA10 AND C > MA20 AND MA10 > MA20 AND MA20 > Ref( MA20, -5 )
           AND Sum( C >= MA20, 10 ) >= SurfDays;

Pivot     = HHV( H, PivotLen );                 // tomorrow's trigger level
NearPivot = C >= Pivot * ( 1 - NearPct / 100 );

//------------------------------------------------------------------------------
// WATCHLIST condition (setup ready, waiting for the breakout)
//------------------------------------------------------------------------------
Ready = Liquid AND Leader AND Surge AND ConsOK AND Pullback
        AND ( HigherLo OR ! ReqHL ) AND Tight AND Surf AND NearPivot AND MarketOK;

//------------------------------------------------------------------------------
// 4) BREAKOUT BAR - range expansion above the prior bar's pivot
//------------------------------------------------------------------------------
TrigPx   = Ref( Pivot, -1 );
EntryPx  = Max( O, TrigPx );                    // gap-through fills at the open
RangeOK  = ( H - L ) >= RangeExp * Ref( MA( H - L, 14 ), -1 );
VolOK    = V >= VolMult * Ref( MA( V, 20 ), -1 );

// 5) stop = low of the entry day, must not be wider than ADR
StopPct  = 100 * ( EntryPx - L ) / EntryPx;
StopOK   = StopPct <= Ref( ADR, -1 );

BrkBar   = Ref( Ready, -1 ) AND H > TrigPx AND RangeOK AND VolOK AND StopOK;

//------------------------------------------------------------------------------
// EXPLORATION
//------------------------------------------------------------------------------
if( Status( "action" ) == actionExplore )
{
    Filter = Ready OR BrkBar;

    AddTextColumn( WriteIf( BrkBar, "BREAKOUT", "WATCH" ), "Status", 1.0,
                   colorDefault, IIf( BrkBar, colorGreen, colorDefault ), 80 );
    AddColumn( C,       "Close",            1.2 );
    AddColumn( Pivot,   "Trigger (next)",   1.2 );
    AddColumn( ADR,     "ADR %",            1.1 );
    AddColumn( Roc1,    "1M %",             1.0 );
    AddColumn( Roc3,    "3M %",             1.0 );
    AddColumn( Roc6,    "6M %",             1.0 );
    AddColumn( ( SurgeHi / SurgeLo - 1 ) * 100, "Surge %", 1.0 );
    AddColumn( ConsBars, "Cons. bars",      1.0 );
    AddColumn( StopPct, "Stop % (today)",   1.1 );
    AddColumn( Rk1,     "Rank 1M",          1.0 );
    AddColumn( Rk3,     "Rank 3M",          1.0 );
    AddColumn( Rk6,     "Rank 6M",          1.0 );
}

//------------------------------------------------------------------------------
// TRADE LOGIC (scan / backtest): per-bar loop so the stop, break-even move,
// partial exit and MA trail all follow the article.
//------------------------------------------------------------------------------
TrailMA = MA( C, TrailLen );

// Scale-in / scale-out signal codes for the portfolio backtester.
// Defined here because some AmiBroker builds report them as uninitialized.
sigScaleIn  = 2;
sigScaleOut = 3;

Buy = Sell = Short = Cover = 0 * C;
BuyPrice  = EntryPx;
SellPrice = C;

inPos = 0; stopPx = 0; ePx = 0; eBar = 0; partDone = 0;

for( b = 1; b < BarCount; b++ )
{
    if( ! inPos )
    {
        if( BrkBar[ b ] )
        {
            Buy[ b ] = 1;
            inPos    = 1;
            ePx      = EntryPx[ b ];
            stopPx   = L[ b ];                  // low of the entry day
            eBar     = b;
            partDone = 0;
        }
    }
    else
    {
        if( L[ b ] <= stopPx )                  // hard stop (gap-aware)
        {
            Sell[ b ]      = 1;
            SellPrice[ b ] = Min( O[ b ], stopPx );
            inPos          = 0;
        }
        else if( C[ b ] < TrailMA[ b ] )        // first CLOSE below trail MA
        {
            Sell[ b ]      = 1;
            SellPrice[ b ] = C[ b ];
            inPos          = 0;
        }
        else if( PartialOn AND ! partDone AND ( b - eBar ) >= PartialDay AND C[ b ] > ePx )
        {
            Buy[ b ]       = sigScaleOut;       // scale-out goes in the BUY array
            BuyPrice[ b ]  = C[ b ];            // (sell 1/3 - 1/2 of the position)
            partDone       = 1;
            stopPx         = Max( stopPx, ePx ); // stop to break-even
        }
    }
}

//------------------------------------------------------------------------------
// BACKTEST SETTINGS & POSITION SIZING (risk / stop distance, capped)
//------------------------------------------------------------------------------
SetTradeDelays( 0, 0, 0, 0 );                   // entries/exits modelled on signal bar
SetOption( "MaxOpenPositions", MaxOpen );
SetOption( "InitialEquity", 1000000 );

PosPct       = Min( MaxPosPct, RiskPct / Max( StopPct, 0.5 ) * 100 );
// entries: % of equity; scale-out bars: % of the currently open position
SetPositionSize( IIf( Buy == sigScaleOut, PartialPct, PosPct ),
                 IIf( Buy == sigScaleOut, spsPercentOfPosition, spsPercentOfEquity ) );
PositionScore = Ref( Roc3, -1 );                // prefer the strongest leaders

//------------------------------------------------------------------------------
// CHART
//------------------------------------------------------------------------------
if( Status( "action" ) == actionIndicator )
{
    _N( Title = StrFormat( "{{NAME}}  {{DATE}}  O %g  H %g  L %g  C %g  ADR %.1f%%  Trigger %g  %s",
                           O, H, L, C, ADR, Pivot,
                           WriteIf( BrkBar, "BREAKOUT", WriteIf( Ready, "WATCH", "" ) ) ) );

    Plot( C, "Price", colorDefault, styleCandle );
    Plot( MA10, "10d MA", colorYellow,     styleLine | styleThick );
    Plot( MA20, "20d MA", colorLightBlue,  styleLine | styleThick );
    Plot( MA50, "50d MA", colorGrey50,     styleLine );
    Plot( IIf( Ready, Pivot, Null ), "Trigger", colorOrange, styleDashed );

    PlotShapes( IIf( Ready AND ! BrkBar, shapeSmallCircle, shapeNone ), colorYellow, 0, H, 12 );
    PlotShapes( IIf( BrkBar, shapeUpArrow, shapeNone ), colorBrightGreen, 0, L, -18 );
    PlotShapes( IIf( Sell == 1, shapeDownArrow, shapeNone ), colorRed, 0, H, -18 );
    PlotShapes( IIf( Buy == sigScaleOut, shapeHollowDownArrow, shapeNone ), colorOrange, 0, H, -18 );
}
