// QULLAMAGGIE BREAKOUT — DAILY AFL
// Breakout entry, initial stop, partial exit,
// break-even stop and 10/20-day MA trailing exit.

_SECTION_BEGIN("Qullamaggie Breakout");

// User choices
BaseDays = Param("Base length (days)", 20, 10, 40, 1);
PriorRiseMin = Param("Prior rise minimum %", 30, 30, 100, 5);
PartialDays = Param("Partial exit after days", 4, 3, 5, 1);
PartialPct = Param("Partial exit %", 50, 33, 50, 1);
TrailPeriod = Param("Trailing MA", 10, 10, 20, 10);

// Leading move and consolidation
PriorLow = Ref(LLV(L, 60), -20);
PriorRise = 100 * (C / PriorLow - 1);

BaseHigh = Ref(HHV(H, BaseDays), -1);
BaseLow = Ref(LLV(L, BaseDays), -1);

OldHigh = Ref(HHV(H, BaseDays * 2), -BaseDays);
OldLow = Ref(LLV(L, BaseDays * 2), -BaseDays);

BaseRange = 100 * (BaseHigh - BaseLow) / BaseLow;
OldRange = 100 * (OldHigh - OldLow) / OldLow;

MA10 = MA(C, 10);
MA20 = MA(C, 20);
MA50 = MA(C, 50);

LeadingMove = PriorRise >= PriorRiseMin;
TightBase = BaseRange < OldRange;
MACondition = C > MA10 AND C > MA20
              AND MA10 > Ref(MA10, -5);

Breakout = C > BaseHigh
           AND Ref(C, -1) <= Ref(BaseHigh, -1);

BuySignal = LeadingMove AND TightBase
            AND MACondition AND Breakout;

// One position per symbol; portfolio settings
SetOption("InitialEquity", 1000000);
SetOption("MaxOpenPositions", 20);
SetOption("AllowPositionShrinking", True);
SetPositionSize(100, spsPercentOfEquity);

// Signals use next-bar execution
SetTradeDelays(1, 1, 1, 1);

Buy = BuySignal;
BuyPrice = Open;

// Remember breakout-day low and entry price
EntryLow = ValueWhen(BuySignal, L);
EntryPrice = ValueWhen(BuySignal, Ref(C, 1));
HeldBars = BarsSince(Buy);

InitialStop = L <= EntryLow;

// Partial exit signal after selected number of bars
PartialSignal = HeldBars == PartialDays;

// Breakeven stop after partial exit
PartialOccurred = BarsSince(PartialSignal) >= 0
                  AND HeldBars > PartialDays;

BreakEvenStop = PartialOccurred AND L <= EntryPrice;

// Trailing exit
TrailMA = MA(C, TrailPeriod);
TrailExit = PartialOccurred AND C < TrailMA;

// Full exits
Sell = InitialStop OR BreakEvenStop OR TrailExit;
SellPrice = IIf(InitialStop, EntryLow,
            IIf(BreakEvenStop, EntryPrice, C));

// Plot
Plot(C, "Price", colorDefault, styleCandle);
Plot(MA10, "10-day MA", colorGreen, styleLine);
Plot(MA20, "20-day MA", colorBlue, styleLine);
Plot(MA50, "50-day MA", colorOrange, styleLine);

PlotShapes(IIf(Buy, shapeUpArrow, shapeNone),
           colorGreen, 0, L, -15);
PlotShapes(IIf(Sell, shapeDownArrow, shapeNone),
           colorRed, 0, H, -15);

