// MINERVINI-STYLE MOMENTUM FRAMEWORK (Daily)  -  AmiBroker AFL
//
//  A) TREND TEMPLATE (stage-2 uptrend filter)
//     1. Price above the 150-day and 200-day MA
//     2. 150-day MA above the 200-day MA
//     3. 200-day MA rising for at least 1 month (ideally 4-5 months)
//     4. 50-day MA above both the 150-day and 200-day MA
//     5. Price above the 50-day MA
//     6. Price at least 30% above its 52-week low
//     7. Price within 25% of its 52-week high
//     8. Relative strength rank of 70 or better (higher is better)
//
//  B) VCP (volatility contraction pattern) - 2 to 6 pullbacks, each shallower
//     than the last, volume drying up. Here: 2 or 3 successive equal-length
//     windows whose high-low depth shrinks (an objective approximation of
//     swing pullbacks), plus a volume dry-up test.
//
//  C) ENTRY  : break above the pivot (high of the last contraction) on
//              expanded volume, not extended beyond the pivot.
//  D) STOP   : just below the low of the last contraction, but never wider
//              than a maximum % (default 8%).
//  E) EXITS  : sell part into strength at a profit target (stop to break-even),
//              exit the rest on a close below the trailing MA (50-day SMA,
//              21-day EMA or 10-day SMA).
//  F) RISK   : fixed % of equity risked per trade, position size capped.
//
// SOURCED vs MY DEFAULTS
//  - Rules 1-7, the 2-6 shrinking pullbacks, volume drying up, pivot entry and
//    "stop just below the prior contraction low" come from the ProRealCode
//    trend-template page and the TrendSpider VCP article.
//  - Rule 8 (RS >= 70), the 8% max stop, the ~20% profit target and the
//    breakout-volume multiple are from my recollection of Minervini's
//    published guidance, not from those pages. All of them are parameters.
//  - The RS score below approximates the IBD-style weighted 12-month
//    performance (40% on the latest quarter, 20% on each earlier one). It is
//    NOT the official IBD RS Rating.
//
// HOW TO USE
//  - Chart  : yellow dot = setup ready, green arrow = breakout bar,
//             orange line = tomorrow's pivot.
//  - Explore: shows "WATCH" and "BREAKOUT" rows, or every stock passing the
//             Trend Template if you pick that mode. Run after the close.
//  - Scan / Backtest: buy signals on breakout bars; partial exits are
//             scale-out signals (Buy = sigScaleOut).
//  - Rank mode (needs a watchlist) turns on the true percentile RS test.
//==============================================================================

_SECTION_BEGIN("MM - Universe");
MinPrice     = Param("Min price", 20, 0, 100000, 1);
MinTradedVal = Param("Min avg traded value (50d, close*vol)", 10000000, 0, 1e12, 1000000);
_SECTION_END();

_SECTION_BEGIN("MM - Trend Template");
SlopeBars  = Param("200d MA rising for N bars (21 = 1mo, ~105 = 5mo)", 21, 5, 130, 1);
AboveLow   = Param("Min % above 52-week low", 30, 0, 200, 5);
BelowHigh  = Param("Max % below 52-week high", 25, 1, 60, 1);
UseRank    = ParamToggle("RS percentile vs watchlist (Explore/Scan/Backtest only)", "Off|On", 0);
WLNo       = Param("Watchlist no. used for RS ranking", 0, 0, 255, 1);
RSMin      = Param("Min RS percentile (rank mode)", 70, 1, 99, 1);
RSScoreMin = Param("Fallback: min weighted RS score %", 30, -50, 500, 5);
_SECTION_END();

_SECTION_BEGIN("MM - VCP");
ContrLen   = Param("Contraction window (bars, 15 = 3 weeks)", 15, 5, 40, 1);
NumContr   = Param("Contractions to require (2 or 3)", 3, 2, 3, 1);
FirstMax   = Param("Oldest window max depth %", 40, 10, 80, 1);
FinalMax   = Param("Latest window max depth %", 10, 3, 30, 0.5);
DryRatio   = Param("Volume dry-up: avg vol(10d) < x * avg vol(50d)", 0.9, 0.3, 1.2, 0.05);
NearPct    = Param("Close within % of pivot", 5, 0.5, 15, 0.5);
_SECTION_END();

_SECTION_BEGIN("MM - Entry / Exit / Risk");
BrkVol     = Param("Breakout volume >= x * 50d avg volume", 1.4, 0.5, 5, 0.1);
MaxExt     = Param("Max % entry above pivot", 5, 0.5, 15, 0.5);
MaxStopPct = Param("Max stop distance %", 8, 2, 20, 0.5);
PartialOn  = ParamToggle("Take partial profit", "No|Yes", 1);
ProfitTgt  = Param("Partial profit target %", 20, 5, 100, 1);
PartialPct = Param("Partial % of position", 50, 10, 90, 1);
TrailType  = ParamList("Trailing exit (close below)", "50-day SMA|21-day EMA|10-day SMA", 0);
RiskPct    = Param("Risk per trade % of equity", 1.0, 0.1, 3, 0.05);
MaxPosPct  = Param("Max position % of equity", 25, 5, 100, 1);
MaxOpen    = Param("Max open positions", 8, 1, 50, 1);
_SECTION_END();

_SECTION_BEGIN("MM - Market filter / Explore");
IdxSym   = ParamStr("Market index symbol (blank = off)", "");
ExpMode  = ParamList("Explore mode", "Setups (WATCH/BREAKOUT)|Trend Template only", 0);
_SECTION_END();

//------------------------------------------------------------------------------
// Optional market filter: index above its rising 50d MA and 50d > 200d
//------------------------------------------------------------------------------
MarketOK = 1;
if( IdxSym != "" )
{
    SetForeign( IdxSym );
    ixC   = C;
    ixM50 = MA( C, 50 );
    ixM200 = MA( C, 200 );
    RestorePriceArrays();
    MarketOK = ixC > ixM50 AND ixM50 > ixM200;
}

//------------------------------------------------------------------------------
// Basic arrays
//------------------------------------------------------------------------------
MA50   = MA( C, 50 );
MA150  = MA( C, 150 );
MA200  = MA( C, 200 );
Hi52   = HHV( H, 252 );
Lo52   = LLV( L, 252 );
TrdVal = MA( C * V, 50 );
Liquid = C >= MinPrice AND TrdVal >= MinTradedVal;

// IBD-style weighted performance (approximation, ~63-bar quarters)
RSScore = 0.4 * ROC( C, 63 ) + 0.2 * ROC( C, 126 ) + 0.2 * ROC( C, 189 ) + 0.2 * ROC( C, 252 );

//------------------------------------------------------------------------------
// Rule 8: relative strength (percentile across a watchlist, or fallback score)
//------------------------------------------------------------------------------
RankMode = UseRank AND Status( "action" ) != actionIndicator;
RSPct = 0 * C;

if( RankMode )
{
    if( Status( "stocknum" ) == 0 )
    {
        List = CategoryGetSymbols( categoryWatchlist, WLNo );
        StaticVarSet( "mmTotal", StrCount( List, "," ) + 1 );

        for( k = 0; ( Sym = StrExtract( List, k ) ) != ""; k++ )
        {
            SetForeign( Sym );
            StaticVarSet( "mmrs" + Sym,
                0.4 * ROC( C, 63 ) + 0.2 * ROC( C, 126 ) + 0.2 * ROC( C, 189 ) + 0.2 * ROC( C, 252 ) );
            RestorePriceArrays();
        }
        StaticVarGenerateRanks( "rank", "mmrs", 0, 1224 );
    }

    ThisSym = Name();
    Rk  = Nz( StaticVarGet( "rankmmrs" + ThisSym ), 999999 );
    Tot = Max( StaticVarGet( "mmTotal" ), 1 );
    RSPct = 100 * ( Tot - Rk + 1 ) / Tot;       // assumes rank 1 = strongest
    T8 = RSPct >= RSMin;
}
else
{
    T8 = RSScore >= RSScoreMin;
}

//------------------------------------------------------------------------------
// TREND TEMPLATE
//------------------------------------------------------------------------------
T1 = C > MA150 AND C > MA200;
T2 = MA150 > MA200;
T3 = Sum( MA200 > Ref( MA200, -1 ), SlopeBars ) == SlopeBars;
T4 = MA50 > MA150 AND MA50 > MA200;
T5 = C > MA50;
T6 = C >= Lo52 * ( 1 + AboveLow / 100 );
T7 = C >= Hi52 * ( 1 - BelowHigh / 100 );

TTCount = T1 + T2 + T3 + T4 + T5 + T6 + T7 + T8;
TT      = TTCount == 8;

//------------------------------------------------------------------------------
// VCP: successive equal-length windows with shrinking depth + volume dry-up
//------------------------------------------------------------------------------
w  = ContrLen;
D1 = 100 * ( HHV( H, w ) - LLV( L, w ) ) / HHV( H, w );   // latest window
D2 = Ref( D1, -w );
D3 = Ref( D1, -2 * w );

if( NumContr == 3 )
    ContrOK = D1 < D2 AND D2 < D3 AND D1 <= FinalMax AND D3 <= FirstMax;
else
    ContrOK = D1 < D2 AND D1 <= FinalMax AND D2 <= FirstMax;

DryUp = MA( V, 10 ) < DryRatio * MA( V, 50 );

Pivot     = HHV( H, w );                           // tomorrow's trigger
NearPivot = C >= Pivot * ( 1 - NearPct / 100 );

Ready = TT AND Liquid AND ContrOK AND DryUp AND NearPivot AND MarketOK;

//------------------------------------------------------------------------------
// BREAKOUT BAR, STOP LEVEL
//------------------------------------------------------------------------------
TrigPx  = Ref( Pivot, -1 );
EntryPx = Max( O, TrigPx );
VolOK   = V >= BrkVol * Ref( MA( V, 50 ), -1 );
NotExt  = EntryPx <= TrigPx * ( 1 + MaxExt / 100 );

// stop: just below the prior contraction low, capped at MaxStopPct
StopLevel = Max( EntryPx * ( 1 - MaxStopPct / 100 ), Ref( LLV( L, w ), -1 ) );
StopPct   = 100 * ( EntryPx - StopLevel ) / EntryPx;
StopSafe  = L > StopLevel;                         // entry bar did not hit the stop

BrkBar = Ref( Ready, -1 ) AND H > TrigPx AND VolOK AND NotExt AND StopSafe;

//------------------------------------------------------------------------------
// EXPLORATION
//------------------------------------------------------------------------------
if( Status( "action" ) == actionExplore )
{
    if( ExpMode == "Trend Template only" )
        Filter = TT AND Liquid AND MarketOK;
    else
        Filter = Ready OR BrkBar;

    AddTextColumn( WriteIf( BrkBar, "BREAKOUT", WriteIf( Ready, "WATCH", "TT" ) ), "Status", 1.0,
                   colorDefault, IIf( BrkBar, colorGreen, colorDefault ), 80 );
    AddColumn( C,       "Close",          1.2 );
    AddColumn( Pivot,   "Pivot (next)",   1.2 );
    AddColumn( TTCount, "TT rules met",   1.0 );
    AddColumn( RSScore, "RS score %",     1.1 );
    AddColumn( RSPct,   "RS percentile",  1.0 );
    AddColumn( D3,      "Depth 3 (old) %", 1.1 );
    AddColumn( D2,      "Depth 2 %",      1.1 );
    AddColumn( D1,      "Depth 1 (new) %", 1.1 );
    AddColumn( 100 * ( C / Hi52 - 1 ), "vs 52w high %", 1.1 );
    AddColumn( StopPct, "Stop % (today)", 1.1 );
}

//------------------------------------------------------------------------------
// TRADE LOGIC (scan / backtest)
//------------------------------------------------------------------------------
if( TrailType == "21-day EMA" )      TrailMA = EMA( C, 21 );
else if( TrailType == "10-day SMA" ) TrailMA = MA( C, 10 );
else                                 TrailMA = MA( C, 50 );

// Scale-in / scale-out signal codes for the portfolio backtester.
// Defined here because some AmiBroker builds report them as uninitialized.
sigScaleIn  = 2;
sigScaleOut = 3;

Buy = Sell = Short = Cover = 0 * C;
BuyPrice  = EntryPx;
SellPrice = C;

inPos = 0; stopPx = 0; ePx = 0; eBar = 0; partDone = 0;

for( b = 1; b < BarCount; b++ )
{
    if( ! inPos )
    {
        if( BrkBar[ b ] )
        {
            Buy[ b ] = 1;
            inPos    = 1;
            ePx      = EntryPx[ b ];
            stopPx   = StopLevel[ b ];
            eBar     = b;
            partDone = 0;
        }
    }
    else
    {
        tgtPx = ePx * ( 1 + ProfitTgt / 100 );

        if( L[ b ] <= stopPx )                      // hard stop (gap-aware)
        {
            Sell[ b ]      = 1;
            SellPrice[ b ] = Min( O[ b ], stopPx );
            inPos          = 0;
        }
        else if( C[ b ] < TrailMA[ b ] )            // close below trailing MA
        {
            Sell[ b ]      = 1;
            SellPrice[ b ] = C[ b ];
            inPos          = 0;
        }
        else if( PartialOn AND ! partDone AND H[ b ] >= tgtPx )
        {
            Buy[ b ]       = sigScaleOut;           // sell into strength
            BuyPrice[ b ]  = Max( O[ b ], tgtPx );
            partDone       = 1;
            stopPx         = Max( stopPx, ePx );    // stop to break-even
        }
    }
}

//------------------------------------------------------------------------------
// BACKTEST SETTINGS & POSITION SIZING
//------------------------------------------------------------------------------
SetTradeDelays( 0, 0, 0, 0 );
SetOption( "MaxOpenPositions", MaxOpen );
SetOption( "InitialEquity", 1000000 );

PosPct = Min( MaxPosPct, RiskPct / Max( StopPct, 0.5 ) * 100 );
// entries: % of equity; scale-out bars: % of the currently open position
SetPositionSize( IIf( Buy == sigScaleOut, PartialPct, PosPct ),
                 IIf( Buy == sigScaleOut, spsPercentOfPosition, spsPercentOfEquity ) );
PositionScore = Ref( RSScore, -1 );

//------------------------------------------------------------------------------
// CHART
//------------------------------------------------------------------------------
if( Status( "action" ) == actionIndicator )
{
    _N( Title = StrFormat( "{{NAME}}  {{DATE}}  O %g  H %g  L %g  C %g  TT %g/8  Pivot %g  %s",
                           O, H, L, C, TTCount, Pivot,
                           WriteIf( BrkBar, "BREAKOUT", WriteIf( Ready, "WATCH", "" ) ) ) );

    Plot( C, "Price", colorDefault, styleCandle );
    Plot( MA50,  "50d MA",  colorYellow,    styleLine | styleThick );
    Plot( MA150, "150d MA", colorLightBlue, styleLine );
    Plot( MA200, "200d MA", colorRed,       styleLine | styleThick );
    Plot( IIf( Ready, Pivot, Null ), "Pivot", colorOrange, styleDashed );

    PlotShapes( IIf( Ready AND ! BrkBar, shapeSmallCircle, shapeNone ), colorYellow, 0, H, 12 );
    PlotShapes( IIf( BrkBar, shapeUpArrow, shapeNone ), colorBrightGreen, 0, L, -18 );
    PlotShapes( IIf( Sell == 1, shapeDownArrow, shapeNone ), colorRed, 0, H, -18 );
    PlotShapes( IIf( Buy == sigScaleOut, shapeHollowDownArrow, shapeNone ), colorOrange, 0, H, -18 );
}
","description":"","kind":"system","weight":null,"created":1792745070192,"updated":1792745070192},{"id":"u:mvkw6ouz0","name":"Rising 44","code":"//==============================================================
//  Siddharth Bhanushali - Rising 44 MA Strategy
//  Updated: Buy only when High > BuyPrice
//           Short only when Low < ShortPrice
//==============================================================

_SECTION_BEGIN("Rising 44 MA Strategy - Siddharth Bhanushali");

//========== Parameters ==========
MA_Period       = Param("MA Period", 44, 20, 100, 1);
RisingBars      = Param("Rising Bars Check", 3, 1, 10, 1);
NearMA_Percent  = Param("Near MA %", 1.5, 0.5, 5, 0.1);
RR_Ratio        = Param("Risk Reward Ratio", 2, 1, 5, 0.5);
ShowShort       = ParamToggle("Show Short Side", "No|Yes", 0);

//========== Calculations ==========
MA44 = MA(C, MA_Period);

// Rising / Falling MA
RisingMA = True;
FallingMA = True;
for(i = 1; i <= RisingBars; i++)
{
    RisingMA  = RisingMA  AND (MA44 > Ref(MA44, -i));
    FallingMA = FallingMA AND (MA44 < Ref(MA44, -i));
}

// Support / Resistance zone
NearMA_Long  = (L <= MA44 * (1 + NearMA_Percent/100)) AND (H >= MA44 * (1 - NearMA_Percent/100));
NearMA_Short = (H >= MA44 * (1 - NearMA_Percent/100)) AND (L <= MA44 * (1 + NearMA_Percent/100));

// Candle color
BullishCandle = C > O;
BearishCandle = C < O;

//========== Signal Candle Detection ==========
BuySetup   = RisingMA  AND NearMA_Long  AND BullishCandle;
ShortSetup = FallingMA AND NearMA_Short AND BearishCandle;

// Store the levels of the signal candle
BuyLevel   = ValueWhen(BuySetup, H);     // Buy above this high
SL_Long    = ValueWhen(BuySetup, L);     // Stop loss below this low

ShortLevel = ValueWhen(ShortSetup, L);   // Short below this low
SL_Short   = ValueWhen(ShortSetup, H);   // Stop loss above this high

//========== Actual Entry Conditions (Your Request) ==========
// Buy only when High crosses above the BuyLevel of signal candle
Buy  = Cross(H, BuyLevel) AND BuyLevel > 0;

// Short only when Low crosses below the ShortLevel of signal candle
Short = IIf(ShowShort, Cross(ShortLevel, L) AND ShortLevel > 0, 0);

// Reset after entry (optional safety)
Buy  = ExRem(Buy, Short);
Short = ExRem(Short, Buy);

//========== Exit (Stop Loss + Target) ==========
Sell  = 0;
Cover = 0;

Risk_Long  = BuyLevel - SL_Long;
Risk_Short = SL_Short - ShortLevel;

ApplyStop(stopTypeLoss,   stopModePoint, Risk_Long,  True, False);
ApplyStop(stopTypeProfit, stopModePoint, Risk_Long * RR_Ratio, True, False);

//========== Plotting ==========
SetChartOptions(0, chartShowArrows | chartShowDates);
_N(Title = StrFormat("{{NAME}} - {{INTERVAL}} {{DATE}}  Open %g, Hi %g, Lo %g, Close %g (%.1f%%) {{VALUES}}", 
             O, H, L, C, SelectedValue(ROC(C, 1))));

Plot(C, "Close", colorDefault, styleNoTitle | styleCandle);

// 44 MA colored
MA_Color = IIf(RisingMA, colorBrightGreen, IIf(FallingMA, colorRed, colorYellow));
Plot(MA44, "44 SMA", MA_Color, styleThick);

// Plot signal levels (optional visual help)
Plot(BuyLevel, "Buy Level", colorBrightGreen, styleDashed | styleNoRescale);
Plot(ShortLevel, "Short Level", colorRed, styleDashed | styleNoRescale);

// Arrows
PlotShapes(IIf(BuySetup, shapeSmallUpTriangle, shapeNone), colorBrightGreen, 0, L, -25);  // Setup candle
PlotShapes(IIf(Buy, shapeUpArrow, shapeNone), colorGreen, 0, L, -45);                      // Actual Buy

PlotShapes(IIf(ShortSetup AND ShowShort, shapeSmallDownTriangle, shapeNone), colorOrange, 0, H, -25);
PlotShapes(IIf(Short, shapeDownArrow, shapeNone), colorRed, 0, H, -45);

//========== Exploration ==========
Filter = Buy OR Short OR BuySetup OR (ShortSetup AND ShowShort);

AddColumn(C, "Close", 1.2);
AddColumn(MA44, "44 MA", 1.2);
AddColumn(BuySetup, "Buy Setup", 1.0);
AddColumn(Buy, "Buy Triggered", 1.0);
AddColumn(BuyLevel, "Buy Above", 1.2);
AddColumn(SL_Long, "SL Long", 1.2);
AddColumn(ShortSetup, "Short Setup", 1.0);
AddColumn(Short, "Short Triggered", 1.0);
AddColumn(ShortLevel, "Short Below", 1.2);
AddColumn(SL_Short, "SL Short", 1.2);

