//  Alok Jain Style - Multi RSI Momentum (Final Clean Version)
//  22 / 44 / 66 RSI + Nifty Trend Filter
//  Buy: Signal High + 0.5%   |  Sell: Next Bar Open
//  Initial SL 20%  |  ATR Chandelier Trail (1.8)  |  Comm+Slip 1%
//==============================================================

_SECTION_BEGIN("Alok Jain Multi-RSI Momentum Final");

//========== Parameters ==========
RSI1 = Param("RSI Period 1 (≈1M)", 22, 10, 50, 1);
RSI2 = Param("RSI Period 2 (≈2M)", 44, 20, 80, 1);
RSI3 = Param("RSI Period 3 (≈3M)", 66, 30, 100, 1);

MinScore     = Param("Minimum Avg RSI Score", 65, 55, 75, 1);
ROC_Period   = Param("ROC Period (for ranking)", 63, 21, 252, 21);

NiftyLongMA  = Param("Nifty Long MA", 200, 50, 300, 10);
NiftyShortMA = Param("Nifty Short MA", 50, 10, 100, 5);

StockMA      = Param("Stock MA for Strength/Exit", 50, 20, 100, 5);
MaxOpen      = Param("Max Open Positions", 12, 5, 25, 1);

//----- Risk Management Parameters -----
InitialSLPct     = Param("Initial Stop Loss %", 20, 10, 30, 1);
ATRPeriod        = Param("ATR Period", 14, 7, 21, 1);
ATRMultiplier    = Param("ATR Chandelier Multiplier", 1.8, 1.0, 3.0, 0.1);

//========== Calculations ==========
R1 = RSI(RSI1);
R2 = RSI(RSI2);
R3 = RSI(RSI3);

AvgRSI = (R1 + R2 + R3) / 3;
ROC_Val = ROC(C, ROC_Period);

//========== Nifty Trend Filter ==========
NC = Foreign("NIFTY50", "C");

MA_Long  = MA(NC, NiftyLongMA);
MA_Short = MA(NC, NiftyShortMA);

PM       = NC > MA_Short AND MA_Short > MA_Long;
Cashcall = Cross(MA_Long, MA_Short);

//========== Strong Momentum ==========
StrongMomentum = AvgRSI > MinScore AND C > MA(C, StockMA);

//========== Portfolio Settings ==========
SetTradeDelays(0, 0, 0, 0);
SetOption("MaxOpenPositions", MaxOpen);
SetPositionSize(100 / MaxOpen, spsPercentOfEquity);
PositionScore = Ref(AvgRSI, -1);

// Commission + Slippage = 1% round trip (0.5% each side)
SetOption("CommissionMode", 1);          // % of trade
SetOption("CommissionAmount", 0.5);      // 0.5% per side → 1% round trip
SetOption("PriceBoundRoundLotSize", 1);

//========== Raw Signals ==========
BuySetup  = Cross(AvgRSI, MinScore) AND StrongMomentum AND PM;
SellSetup = Cross(MinScore, AvgRSI) OR C < MA(C, StockMA) OR Cashcall;

//==============================================================
//  REALISTIC EXECUTION
//==============================================================
SignalHigh     = ValueWhen(BuySetup, H);
BuyLimitPrice  = SignalHigh * 1.005;               // Signal High + 0.5%

Buy  = Ref(BuySetup, -1) AND H > Ref(SignalHigh, -1);
BuyPrice = BuyLimitPrice;

Sell = Ref(SellSetup, -1);
SellPrice = O;                                     // Next bar Open

Short = 0;
Cover = 0;

//==============================================================
//  RISK MANAGEMENT
//  1. Initial 20% Stop-Loss
//  2. ATR Chandelier Trailing Stop (Multiplier 1.8)
//==============================================================

// ATR for Chandelier
ATRValue = ATR(ATRPeriod);

// Chandelier Trail (Long only) - highest high since entry minus ATR * multiplier
HHVSinceEntry = HighestSince(Buy, H);
ChandelierStop = HHVSinceEntry - ATRMultiplier * ATRValue;

// Initial 20% stop from entry price
EntryPrice = ValueWhen(Buy, BuyPrice);
InitialStop = EntryPrice * (1 - InitialSLPct/100);

// Final Stop = the higher of Initial Stop and Chandelier Trail
// (once Chandelier moves above Initial Stop it takes over)
FinalStop = Max(InitialStop, ChandelierStop);

// Apply the stop
ApplyStop(stopTypeLoss, stopModePercent, InitialSLPct, True);   // Hard 20% initial SL
ApplyStop(stopTypeTrailing, stopModePoint, ATRMultiplier * ATRValue, True, True); // ATR trail

// Optional visual of the stop line
Plot(IIf(Buy OR Flip(Buy, Sell), FinalStop, Null), "Final Stop", colorOrange, styleThick | styleNoRescale);

//==============================================================
//  Plotting
//==============================================================
SetChartOptions(0, chartShowArrows | chartShowDates);
_N(Title = StrFormat("{{NAME}} - AvgRSI: %.1f | ROC: %.1f%%  {{VALUES}}",
             SelectedValue(AvgRSI), SelectedValue(ROC_Val)));

Plot(C, "Close", colorDefault, styleCandle);
Plot(MA(C, StockMA), "Stock MA", colorYellow, styleThick);

Plot(AvgRSI, "Avg RSI Score", colorBrightGreen, styleThick | styleOwnScale);
Plot(MinScore, "Min Score", colorRed, styleDashed | styleOwnScale);

PlotShapes(IIf(BuySetup, shapeSmallCircle, shapeNone), colorBlue, 0, H, 15);
PlotShapes(IIf(Buy, shapeUpArrow, shapeNone), colorBrightGreen, 0, L, -30);
PlotShapes(IIf(SellSetup, shapeSmallCircle, shapeNone), colorOrange, 0, L, -15);
PlotShapes(IIf(Sell, shapeDownArrow, shapeNone), colorRed, 0, H, -30);

//==============================================================
//  Exploration
//==============================================================
Filter = AvgRSI > MinScore AND C > MA(C, StockMA) AND PM;

AddColumn(AvgRSI, "Avg RSI Score", 1.2);
AddColumn(R1, "RSI-22", 1.1);
AddColumn(R2, "RSI-44", 1.1);
AddColumn(R3, "RSI-66", 1.1);
AddColumn(ROC_Val, "ROC %", 1.2);
AddColumn(C, "Close", 1.2);
AddColumn(MA(C, StockMA), "Stock MA", 1.2);
AddColumn(IIf(PM, 1, 0), "Nifty Uptrend", 1.0);

SetSortColumns(-3);

