//==================== EXIT ====================
Exit1_RSI = Cross(Exit_RSI_Level, AvgRSI);           // Avg RSI falls below exit level
Exit2_MA  = Use_MA_Exit AND Cross(MA_Filter_Line, C); // Close below MA filter

