Plot(AvgRSI, "Avg RSI Score", colorBrightGreen, styleThick | styleOwnScale);
Plot(Min_AvgRSI, "Min Entry Level", colorBlue, styleDashed | styleOwnScale);
Plot(Exit_RSI_Level, "Exit RSI Level", colorRed, styleDashed | styleOwnScale);

