//  Rakesh Pujara Momentum Strategy - FULLY OPTIMIZABLE
//  Entry  : Weekly Close > Bollinger Upper Band
//  Exit 1 : Initial % Stop Loss
//  Exit 2 : Close below Exit MA
//  Exit 3 : ATR Trailing Stop
//==============================================================

_SECTION_BEGIN("Rakesh Pujara - Optimizable");

//==================== OPTIMIZABLE PARAMETERS ====================
BB_Period      = Optimize("BB Period", 55, 30, 80, 5);
BB_Dev         = Optimize("BB Deviation", 3.7, 2.5, 4.5, 0.1);

MA_Exit_Period = Optimize("Exit MA Period", 23, 15, 40, 1);

ATR_Period     = Optimize("ATR Period", 14, 7, 21, 1);
ATR_Mult       = Optimize("ATR Multiplier", 1.8, 1.2, 2.5, 0.1);

Initial_SL_Pct = Optimize("Initial SL %", 20, 12, 30, 1);

//==================== INDICATORS ====================
// Bollinger Bands
MidBB   = MA(C, BB_Period);
StdDev  = StDev(C, BB_Period);
UpperBB = MidBB + BB_Dev * StdDev;
LowerBB = MidBB - BB_Dev * StdDev;

// Exit Moving Average
MA_Exit = MA(C, MA_Exit_Period);

// ATR
ATR_Val = ATR(ATR_Period);

//==================== ENTRY ====================
BuySetup = Cross(C, UpperBB);
Buy      = Ref(BuySetup, -1);          // Enter next bar

//==================== THREE EXIT CONDITIONS ====================

// 1. Initial Stop Loss
EntryPrice = ValueWhen(Buy, BuyPrice);
InitialSL  = EntryPrice * (1 - Initial_SL_Pct/100);
Exit1_SL   = C < InitialSL;

// 2. Close below Exit MA
Exit2_MA   = Cross(MA_Exit, C);

// 3. ATR Trailing Stop (Highest High since entry - ATR × Mult)
HighestSinceEntry = HighestSince(Buy, H);
ATR_Trail         = HighestSinceEntry - (ATR_Mult * ATR_Val);
Exit3_ATR         = Cross(ATR_Trail, C);

// Final Sell
Sell = Exit1_SL OR Exit2_MA OR Exit3_ATR;

// Clean signals
Buy  = ExRem(Buy, Sell);
Sell = ExRem(Sell, Buy);

//==================== PLOTTING ====================
SetChartOptions(0, chartShowArrows | chartShowDates);
_N(Title = StrFormat("{{NAME}} - {{INTERVAL}} {{DATE}}  Close %g  {{VALUES}}", C));

Plot(C, "Close", colorDefault, styleCandle);

Plot(UpperBB, "Upper BB", colorBrightGreen, styleThick);
Plot(MidBB, "Mid BB", colorYellow, styleThick);
Plot(LowerBB, "Lower BB", colorRed, styleThick);

Plot(MA_Exit, "Exit MA", colorOrange, styleThick);

// ATR Trail line (only when in position)
TrailLine = IIf(BarsSince(Buy) < BarsSince(Sell), ATR_Trail, Null);
Plot(TrailLine, "ATR Trail", colorAqua, styleThick | styleDots);

PlotShapes(IIf(Buy, shapeUpArrow, shapeNone), colorBrightGreen, 0, L, -40);
PlotShapes(IIf(Sell, shapeDownArrow, shapeNone), colorRed, 0, H, -40);

//==================== EXPLORATION ====================
Filter = Buy OR Sell OR BuySetup;

AddColumn(C, "Close", 1.2);
AddColumn(UpperBB, "Upper BB", 1.2);
AddColumn(MA_Exit, "Exit MA", 1.2);
AddColumn(ATR_Trail, "ATR Trail", 1.2);
AddColumn(Buy, "Buy", 1.0);
AddColumn(Sell, "Sell", 1.0);
AddColumn(Exit1_SL, "Exit1-SL", 1.0);
AddColumn(Exit2_MA, "Exit2-MA", 1.0);
AddColumn(Exit3_ATR, "Exit3-ATR", 1.0);

_SECTION_END();","description":"","kind":"system","weight":null,"created":1792779809994,"updated":1792779815917},{"id":"u:mvlo6kvh0","name":"AlokJain_MultiRSI_Momentum","code":"//==============================================================================
//  MULTI-RSI MOMENTUM (Alok Jain style)  -  daily or weekly, long only
//
//  Idea (from your version): average of three RSIs (22 / 44 / 66) = momentum score.
//  BUY  when the score is strong (> MinScore) AND price is above its trend MA.
//  SELL when the score fades (< ExitScore) OR price closes below the MA (optional).
//
//  What I changed from the pasted version, and why:
//   1. Entry is a STATE (score high AND close above MA), not a one-bar Cross.
//      The Cross version misses the stock if the two conditions become true on
//      different bars. ExRem keeps only the first signal.
//   2. Signals are made on the close and traded at NEXT BAR'S OPEN (explicit
//      Ref -1, delays set to 0). No double delay, no look-ahead.
//   3. Only 3 inputs are optimised (MinScore, MA, ExitScore). The three RSI
//      lengths stay fixed at 22/44/66 so the system keeps its meaning and the
//      search is small enough to run and not over-fit. ROC was removed: it was
//      optimised but never used, which only wastes search time.
//   4. Portfolio rules added: equal-weight slots, strongest score first.
//
//  Use: Analysis -> Optimize / Backtest, Time frame = Daily or Weekly.
//  (On Weekly bars the periods mean weeks: 22/44/66 weeks - very slow.)
//==============================================================================
_SECTION_BEGIN("Multi-RSI Momentum");
P1   = Param("RSI period 1", 22, 5, 60, 1);
P2   = Param("RSI period 2", 44, 10, 100, 1);
P3   = Param("RSI period 3", 66, 20, 150, 1);
MinScore  =Optimize("Min avg RSI to buy", 58,55, 65, 1);
MAper     =Optimize("Trend MA period",   95, 50, 100, 5);
ExitScore = Optimize("Exit when avg RSI below", 40, 40, 50, 1);
UseMAExit = ParamToggle("Also exit on close below MA", "No|Yes", 1);
MaxOpen   = Optimize("Max open positions", 30, 10, 50, 1);
_SECTION_END();

R1 = RSI( P1 ); R2 = RSI( P2 ); R3 = RSI( P3 );
AvgRSI = ( R1 + R2 + R3 ) / 3;
TrendMA = MA( C, MAper );

BuyNow  = AvgRSI > MinScore AND C > TrendMA;
SellNow = AvgRSI < ExitScore OR ( UseMAExit AND C < TrendMA );

BuyNow  = ExRem( BuyNow, SellNow );
SellNow = ExRem( SellNow, BuyNow );

// decided on the close of bar t, executed at the open of bar t+1
Buy  = Ref( BuyNow, -1 );
Sell = Ref( SellNow, -1 );
Short = Cover = 0 * C;
BuyPrice = SellPrice = O;

SetTradeDelays( 0, 0, 0, 0 );
SetOption( "MaxOpenPositions", MaxOpen );
SetPositionSize( 100 / MaxOpen, spsPercentOfEquity );
PositionScore = Ref( AvgRSI, -1 );              // when more signals than slots: strongest first

if( Status( "action" ) == actionExplore )
{
    Filter = BuyNow OR SellNow OR ( AvgRSI > MinScore AND C > TrendMA );
    AddTextColumn( WriteIf( BuyNow, "BUY", WriteIf( SellNow, "SELL", "HOLD/OK" ) ), "Signal", 1.0 );
    AddColumn( AvgRSI, "Avg RSI", 1.2 );
    AddColumn( R1, "RSI 1", 1.1 ); AddColumn( R2, "RSI 2", 1.1 ); AddColumn( R3, "RSI 3", 1.1 );
    AddColumn( C, "Close", 1.2 );
    AddColumn( TrendMA, "Trend MA", 1.2 );
    SetSortColumns( -3 );
}

if( Status( "action" ) == actionIndicator )
{
    _N( Title = StrFormat( "{{NAME}} {{DATE}}  Close %g  AvgRSI %.1f", C, AvgRSI ) );
    Plot( C, "Price", colorDefault, styleCandle );
    Plot( TrendMA, "Trend MA", colorYellow, styleThick );
    Plot( AvgRSI, "Avg RSI", colorBrightGreen, styleThick | styleOwnScale );
    Plot( MinScore, "Entry level", colorBlue, styleDashed | styleOwnScale );
    Plot( ExitScore, "Exit level", colorRed, styleDashed | styleOwnScale );
    PlotShapes( IIf( Buy, shapeUpArrow, shapeNone ), colorBrightGreen, 0, L, -20 );
    PlotShapes( IIf( Sell, shapeDownArrow, shapeNone ), colorRed, 0, H, -20 );
}
","description":"","kind":"system","weight":null,"created":1792802269996,"updated":1792823348028},{"id":"u:mvlo7sjw1","name":"RakeshPujara_BB_Breakout_Momentum","code":"//==============================================================================
//  BOLLINGER-BAND BREAKOUT MOMENTUM (Rakesh Pujara style)  -  long only
//
//  ENTRY : close breaks above the UPPER Bollinger band (wide band: default 55 bars, 3.7 SD).
//  EXITS : whichever comes first
//          1. initial stop: close below entry * (1 - SL%)
//          2. close below the exit MA
//          3. ATR trailing stop: (highest high since entry) - ATR * multiple
//
//  Run it on the WEEKLY time frame (Analysis -> Time frame = Weekly) to match
//  the weekly-chart idea. Daily works too but the numbers then mean days.
//
//  What I changed from the pasted version, and why:
//   1. The pasted version computed the stop and the trailing high from the raw
//      Buy array. A second breakout while you are already holding re-set the
//      entry price and the highest-high, so the stop moved UP/DOWN wrongly.
//      This version tracks ONE position in a loop: entry, stop, and highest high
//      are set once at entry and only the trail can rise.
//   2. Signals are made on the close and traded at the NEXT open (no double
//      delay, no look-ahead).
//   3. Portfolio rules added: equal slots, strongest breakout first.
//==============================================================================
_SECTION_BEGIN("BB Breakout Momentum");
BBper    = Optimize("BB period", 55, 30, 80, 5);
BBdev    = Optimize("BB deviation", 3.7, 2.5, 4.5, 0.2);
ExitMA   = Optimize("Exit MA period", 23, 15, 40, 5);
ATRper   = Param("ATR period", 14, 5, 30, 1);
ATRmult  = Optimize("ATR multiple", 1.8, 1.2, 2.6, 0.2);
SLpct    = Param("Initial stop %", 20, 5, 40, 1);
MaxOpen  = Param("Max open positions", 10, 1, 50, 1);
_SECTION_END();

Mid   = MA( C, BBper );
Upper = Mid + BBdev * StDev( C, BBper );
Lower = Mid - BBdev * StDev( C, BBper );
XMA   = MA( C, ExitMA );
AtrV  = ATR( ATRper );

Setup = Cross( C, Upper );                       // breakout bar (decided at its close)

sigBuy = sigSell = 0 * C;
TrailLine = Null * C;
inPos = 0; ePx = 0; hh = 0; stopPx = 0;

for( b = 1; b < BarCount; b++ )
{
    if( ! inPos )
    {
        if( Setup[ b ] )
        {
            sigBuy[ b ] = 1; inPos = 1;
            ePx = C[ b ];                              // planned entry ~ this close (real fill = next open)
            hh = H[ b ];
            stopPx = ePx * ( 1 - SLpct / 100 );
        }
    }
    else
    {
        hh = Max( hh, H[ b ] );
        tr = hh - ATRmult * AtrV[ b ];
        TrailLine[ b ] = tr;
        if( C[ b ] < stopPx OR C[ b ] < XMA[ b ] OR C[ b ] < tr )
        {
            sigSell[ b ] = 1; inPos = 0;
        }
    }
}

Buy  = Ref( sigBuy, -1 );
Sell = Ref( sigSell, -1 );
Short = Cover = 0 * C;
BuyPrice = SellPrice = O;

SetTradeDelays( 0, 0, 0, 0 );
SetOption( "MaxOpenPositions", MaxOpen );
SetPositionSize( 100 / MaxOpen, spsPercentOfEquity );
PositionScore = Ref( 100 * ( C - Upper ) / Upper, -1 );   // how far through the band: strongest first

if( Status( "action" ) == actionExplore )
{
    Filter = Setup OR sigSell;
    AddTextColumn( WriteIf( Setup, "BREAKOUT", "EXIT" ), "Signal", 1.0 );
    AddColumn( C, "Close", 1.2 );
    AddColumn( Upper, "Upper BB", 1.2 );
    AddColumn( XMA, "Exit MA", 1.2 );
    AddColumn( 100 * ( C / Upper - 1 ), "% above band", 1.1 );
}

if( Status( "action" ) == actionIndicator )
{
    _N( Title = StrFormat( "{{NAME}} {{DATE}}  Close %g", C ) );
    Plot( C, "Price", colorDefault, styleCandle );
    Plot( Upper, "Upper BB", colorBrightGreen, styleThick );
    Plot( Mid, "Mid BB", colorYellow, styleLine );
    Plot( Lower, "Lower BB", colorRed, styleLine );
    Plot( XMA, "Exit MA", colorOrange, styleThick );
    Plot( TrailLine, "ATR trail", colorAqua, styleDots | styleThick );
    PlotShapes( IIf( Buy, shapeUpArrow, shapeNone ), colorBrightGreen, 0, L, -20 );
    PlotShapes( IIf( Sell, shapeDownArrow, shapeNone ), colorRed, 0, H, -20 );
}
","description":"","kind":"system","weight":null,"created":1792802326603,"updated":1793076787854},{"id":"u:mvmvv1vi0","name":"My_formula_v2","code":"//==============================================================================
//  SMA TREND CROSS  v2   (your system, with the weak points fixed)
//  BUY : Fast SMA crosses above Slow SMA   (as before)
//  SELL: Close crosses below Exit SMA      (as before)
//
//  What changed vs your version - change ONE switch at a time and re-run the
//  Walk-Forward, so you can see which change helps and which does not.
//   1. Optimise ranges are small and cannot overlap: Fast 10-100 < Slow 100-250 (DAILY bars).
//      Your old Fast range (20-200) could go ABOVE the slow one, and Slow kept
//      landing on its upper limit (200). Old grid ~140,000 combos, now 960.
//   2. Liquidity filter (price + average traded value) - the old test bought
//      stocks under Rs 20 and thin small caps. Default ON.
//   3. Optional market filter: buy only if an index is above its 200-day SMA.
//      Default OFF (type an index symbol to switch on). Sells are never blocked.
//   4. Optional ranking: when more signals than free slots, take the strongest
//      6-month momentum first. Default OFF.
//   The 20% stop-loss in your results came from the Analysis SETTINGS, not from
//   this formula: keep that setting the same in every test.
//==============================================================================
_SECTION_BEGIN("SMA Trend Cross v2");
FastPeriod = Optimize( "Fast SMA", 20, 10, 100, 10 );
SlowPeriod = Optimize( "Slow SMA", 130, 100, 250, 10 );
ExitPeriod = Optimize( "Exit SMA", 30, 10, 60, 10 );

MinPrice     = Param( "Min price (Rs)", 30, 0, 100000, 5 );
MinTradedVal = Param( "Min avg traded value 50d (Rs)", 10000000, 0, 1e12, 1000000 );
MktSym       = ParamStr( "Market index symbol (blank = off)", "" );
RankOn       = ParamToggle( "Rank signals by 6-month momentum", "Off|On", 0 );
_SECTION_END();

FastSMA = MA( C, FastPeriod );
SlowSMA = MA( C, SlowPeriod );
ExitSMA = MA( C, ExitPeriod );

Liquid = C >= MinPrice AND MA( C * V, 50 ) >= MinTradedVal;

MarketOK = 1;
if( MktSym != "" )
{
    SetForeign( MktSym );
    mc = C;
    RestorePriceArrays();
    MarketOK = mc > MA( mc, 200 );
}

Buy  = Cross( FastSMA, SlowSMA ) AND Liquid AND MarketOK;
Sell = Cross( ExitSMA, C );

Buy  = ExRem( Buy, Sell );
Sell = ExRem( Sell, Buy );

PositionScore = IIf( RankOn, ROC( C, 126 ), 0 );

Plot( C, "Close", colorDefault, styleCandle );
Plot( FastSMA, "Fast SMA", colorGreen, styleLine );
Plot( SlowSMA, "Slow SMA", colorRed, styleLine );
Plot( ExitSMA, "Exit SMA", colorBlue, styleLine );
PlotShapes( IIf( Buy, shapeUpArrow, shapeNone ), colorBrightGreen, 0, L, -20 );
PlotShapes( IIf( Sell, shapeDownArrow, shapeNone ), colorRed, 0, H, -20 );

if( Status( "action" ) == actionExplore )
{
    Filter = Buy OR Sell;
    AddTextColumn( WriteIf( Buy, "BUY", "SELL" ), "Signal", 1.0 );
    AddColumn( C, "Close", 1.2 );
    AddColumn( FastSMA, "Fast SMA", 1.2 );
    AddColumn( SlowSMA, "Slow SMA", 1.2 );
    AddColumn( ExitSMA, "Exit SMA", 1.2 );
    AddColumn( ROC( C, 126 ), "6m ROC %", 1.1 );
}
