","description":"","kind":"chart","weight":null,"created":1793050345492,"updated":1793050345492},{"id":"u:mvq6tilh0","name":"TimeFrame_Weekly_Filter_Example","code":"// Daily system with a weekly trend filter and an index (Nifty 500) filter, using TimeFrameSet like AmiBroker.
Fast = Param("Fast MA", 20, 5, 60, 1);
Slow = Param("Slow MA", 130, 60, 250, 5);
WeeklyLen = Param("Weekly MA length", 10, 3, 40, 1);

