Buy = ExRem( Buy, Sell ); Sell = ExRem( Sell, Buy );

Plot( C, "Price", colorDefault, styleCandle );
Plot( TimeFrameExpand( MA( TimeFrameCompress( C, inWeekly ), WeeklyLen ), inWeekly ), "Weekly MA", colorOrange, styleLine | styleThick );
